import{_ as t,o as r,c as a,a2 as o}from"./chunks/framework.DXa1R37q.js";const h=JSON.parse('{"title":"Requirements","description":"","frontmatter":{},"headers":[],"relativePath":"get-started/requirements.md","filePath":"get-started/requirements.md","lastUpdated":1793129665000}'),i={name:"get-started/requirements.md"};function d(n,e,s,l,c,p){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h1><p>Use this page to decide whether Neottia can safely operate in your environment.</p><h2 id="recommended-user-setup" tabindex="-1">Recommended user setup <a class="header-anchor" href="#recommended-user-setup" aria-label="Permalink to &quot;Recommended user setup&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Component</th><th>Requirement</th></tr></thead><tbody><tr><td>Neottia CLI and MCP servers</td><td>Node.js 22.20 or newer and pnpm 10 or newer</td></tr><tr><td>Pi or OpenCode</td><td>A supported host installation that runs in the target project directory</td></tr><tr><td>Claude Code</td><td>Claude Code, Node.js 22.20 or newer, <code>npx</code> on <code>PATH</code>, and interactive approval of project <code>.mcp.json</code> servers</td></tr><tr><td>Source control</td><td>Git for the default lifecycle configuration</td></tr></tbody></table><p><code>@neottia/core</code> supports Node.js 20 or newer, but the current CLI and distributed runtime packages require the newer user setup above. See the <a href="/projects/neottia/reference/dependencies">dependency reference</a> for exact package-manager, engine, and direct dependency declarations from every module manifest.</p><h2 id="certified-repository-store-tuples" tabindex="-1">Certified Repository Store tuples <a class="header-anchor" href="#certified-repository-store-tuples" aria-label="Permalink to &quot;Certified Repository Store tuples&quot;">​</a></h2><p>Filesystem-backed Memory, Issues, Design Docs, and Searchable use Repository Store. Leased operations fail closed outside these certified tuples:</p><table tabindex="0"><thead><tr><th>Operating system</th><th>Architecture</th><th>Runtime</th><th>Certified local filesystem</th></tr></thead><tbody><tr><td>Linux</td><td>x64, arm64</td><td>Node.js 22.16+ or Bun 1.3.13+</td><td>ext4, XFS, Btrfs, tmpfs, or local overlay</td></tr><tr><td>macOS</td><td>x64, arm64</td><td>Node.js 22.16+ or Bun 1.3.13+</td><td>APFS</td></tr><tr><td>Windows Server 2022/2025</td><td>x64</td><td>Node.js 22.16+ or Bun 1.3.13+</td><td>local NTFS</td></tr><tr><td>FreeBSD 14.x</td><td>x64</td><td>Node.js 22.16+</td><td>local writable UFS2</td></tr></tbody></table><p>Windows arm64, FreeBSD arm64, and FreeBSD Bun are not supported. Network, shared, removable, and uncertified filesystems are not supported for leased operations.</p><p>Run <code>neottia doctor</code> in the actual project directory. Filesystem names alone are not enough: Doctor probes locality, write access, no-replace publication, hard links, stable identity, and durability barriers.</p><h2 id="native-binary-installation" tabindex="-1">Native binary installation <a class="header-anchor" href="#native-binary-installation" aria-label="Permalink to &quot;Native binary installation&quot;">​</a></h2><p>Certified tuples use verified native prebuilds when available. Installation verifies the workflow identity, source commit, tuple, size, SHA-256 digest, Sigstore signature, and GitHub attestation before use. The digest is checked again before the addon loads.</p><p>An availability failure may fall back to a source build. A source build needs Python, Make, a C++17 compiler, and platform headers. An integrity failure does not fall back; reinstall from a trusted package source and investigate the mismatch.</p><h2 id="optional-services" tabindex="-1">Optional services <a class="header-anchor" href="#optional-services" aria-label="Permalink to &quot;Optional services&quot;">​</a></h2><ul><li>PostgreSQL Memory needs PostgreSQL credentials and explicit organization, project, topic, and scope ownership.</li><li>Searchable needs public network access for web retrieval. <code>web_ask</code> additionally needs the configured local Ollama endpoint.</li><li>Remote issue, document, or source-control providers need the connection and credential environment names described in <a href="/projects/neottia/sdlc/providers">provider configuration</a>.</li></ul><p>All capability shards default to disabled unless <code>neottia init</code> enables them. Enable only what the repository uses.</p>',16)])])}const m=t(i,[["render",d]]);export{h as __pageData,m as default};
